function configEngineSettings(state, config) {
  config.max_token_length      = config.max_token_length      ?? 4;
  config.conjunct_support      = config.conjunct_support      ?? true;
  config.zero_width_joiner     = config.zero_width_joiner     ?? '\u200D';
  config.zero_width_non_joiner = config.zero_width_non_joiner ?? '\u200C';
  config.assamese_ra           = config.assamese_ra           ?? '\u09F0'; // ৰ
  config.assamese_wa           = config.assamese_wa           ?? '\u09F1'; // ৱ
  config.virama                = config.virama                ?? '\u09CD'; // ্
  config.inherent_vowel        = config.inherent_vowel        ?? 'o';
  config.unknown_char_handling = config.unknown_char_handling ?? 'passthrough';
  config.non_linking_consonants = config.non_linking_consonants ?? ['ng','M','NG','Ng',':','H','^','~'];
  // Hardcoded-rule toggle flags.
  // Set any of these to false to disable the corresponding built-in rule
  // and handle it yourself via a loop-stage snippet hook instead.
  config.hardcode_independent_vowel = config.hardcode_independent_vowel ?? true;
  config.hardcode_explicit_zwnj     = config.hardcode_explicit_zwnj     ?? true;
  config.hardcode_consonant_matra   = config.hardcode_consonant_matra   ?? true;
  config.hardcode_consonant_cluster = config.hardcode_consonant_cluster ?? true;
  return state;
}

