function preNfcNormalize(state, config) {
  if (typeof state.input === 'string' && state.input.normalize) {
    const before = state.input;
    state.input = state.input.normalize('NFC');
    if (state.input !== before) state.log.push('[PRE] NFC normalisation applied');
  }
  return state;
}

function preRephConjunctions(state, config) {
  const consonants = config.maps.forward.consonants || [];
  const REPH = '\u09F0'; // ৰ
  const sorted = [...consonants].sort((a, b) => b[0].length - a[0].length);
  let input = state.input;
  for (const [roman, bpm] of sorted) {
    if (roman === 'r' || roman === 'rr') continue;
    const rKey = 'r' + roman;
    if (input.includes(rKey)) {
      input = input.split(rKey).join(REPH + bpm);
      state.log.push('[PRE REPH] ' + rKey + ' → ৰ' + bpm);
    }
  }
  state.input = input;
  return state;
}

function preAnusvaraVowelSubstitution(state, config) {
  const NGA = '\u0999'; // ঙ
  const matras = config.maps.forward.matras || [];
  const matraMap = Object.fromEntries(matras.map(p => [p[0], p[1]]));
  const subs = [
    ['ngOI',  NGA + (matraMap['OI']  || '')],
    ['ngOU',  NGA + (matraMap['OU']  || '')],
    ['ngaa',  NGA + (matraMap['aa']  || matraMap['A'] || '')],
    ['ngee',  NGA + (matraMap['ee']  || matraMap['ii'] || '')],
    ['ngii',  NGA + (matraMap['ii']  || '')],
    ['nguu',  NGA + (matraMap['uu']  || matraMap['U'] || '')],
    ['ngA',   NGA + (matraMap['A']   || '')],
    ['ngU',   NGA + (matraMap['U']   || '')],
    ['ngrri', NGA + (matraMap['rri'] || '')],
    ['ngai',  NGA + (matraMap['ai']  || '')],
    ['ngO',   NGA + (matraMap['O']   || '')],
    ['nge',   NGA + (matraMap['e']   || '')],
    ['ngi',   NGA + (matraMap['i']   || '')],
    ['nga',   NGA + (matraMap['a']   || '')],
  ];
  let input = state.input;
  for (const [from, to] of subs) {
    if (to && input.includes(from)) {
      input = input.split(from).join(to);
      state.log.push('[PRE ANUSVARA] ' + from + ' → ' + to);
    }
  }
  state.input = input;
  return state;
}

function preDandaSubstitution(state, config) {
  state.input = state.input.replace(/\.\./g, '॥').replace(/\./g, '।');
  state.log.push('[PRE] danda substitution applied');
  return state;
}

function preAndroidAutocapFix(state, config) {
  if (!state.input) return state;
  const first = state.input[0];
  const lower = first.toLowerCase();
  if (first !== lower) {
    const allKeys = Object.values(config.maps.forward || {}).flat();
    const hasUpper = allKeys.some(p => Array.isArray(p) ? p[0] === first  : false);
    const hasLower = allKeys.some(p => Array.isArray(p) ? p[0] === lower : false);
    if (!hasUpper && hasLower) {
      state.input = lower + state.input.slice(1);
      state.log.push('[PRE] android autocap: lowercased first char');
    }
  }
  return state;
}

function fwdPreSymbolSubstitution(state, config) {
  const punctMap = config.maps.forward.punctuation || [];
  const sorted = [...punctMap].sort((a, b) => b[0].length - a[0].length);
  let input = state.input;
  for (const [sym, bpm] of sorted) {
    if (sym === '..' || sym === '.') continue; // already handled by preDandaSubstitution
    if (input.includes(sym)) {
      input = input.split(sym).join(bpm);
      state.log.push('[FWD PRE SYM] ' + sym + ' → ' + bpm);
    }
  }
  state.input = input;
  return state;
}

function fwdPreNumberSubstitution(state, config) {
  const digitMap = config.maps.forward.digits || [];
  const sorted = [...digitMap].sort((a, b) => b[0].length - a[0].length);
  let input = state.input;
  for (const [latin, native] of sorted) {
    if (input.includes(latin)) {
      input = input.split(latin).join(native);
      state.log.push('[FWD PRE NUM] ' + latin + ' → ' + native);
    }
  }
  state.input = input;
  return state;
}

function preForwardUnknownPassthrough(state, config) {
  config.unknown_char_handling = config.unknown_char_handling ?? 'passthrough';
  return state;
}

function loopRephLigature(state, config) {
  const reph_key = 'r';
  const ZWJ = '\u200D';
  const input = state.input;
  const pos = state.pos;
  if (input[pos] !== reph_key) return state;
  if (input[pos + 1] === reph_key) return state; // 'rr' — skip
  const consonants = (config.maps.forward.consonants || []).map(p => p[0]);
  const nextTokenMatches = consonants.some(c => input.slice(pos + 1).startsWith(c));
  if (!nextTokenMatches) return state;
  const rephPair = (config.maps.forward.consonants || []).find(p => p[0] === reph_key);
  if (!rephPair) return state;
  state.output += rephPair[1] + config.virama + ZWJ;
  state.pos += 1;
  state.log.push('[REPH] reph ligature emitted at pos ' + pos);
  return state;
}

function loopAnusvaraRevertBeforeMatra(state, config) {
  const ANUSVARA = '\u0982'; // ং
  const NGA      = '\u0999'; // ঙ
  if (!state.output.endsWith(ANUSVARA)) return state;
  const matras = (config.maps.forward.matras || []).map(p => p[0]);
  const currentToken = matras.find(m => state.input.slice(state.pos).startsWith(m));
  if (!currentToken) return state;
  state.output = state.output.slice(0, -ANUSVARA.length) + NGA;
  state.log.push('[ANUSVARA REVERT] ং → ঙ before matra at pos ' + state.pos);
  return state;
}

function loopYfalaChaining(state, config) {
  const yfala_keys = ['y', 'Y'];
  const VIRAMA = config.virama;
  const YA_CHAR = '\u09AF'; // য
  const pos = state.input[state.pos];
  if (!yfala_keys.includes(pos)) return state;
  if (!state.prev.was_consonant) return state;
  state.output += VIRAMA + YA_CHAR;
  state.pos += 1;
  state.handled = true;
  state.log.push('[YFALA] ্য chained after consonant at pos ' + state.pos);
  return state;
}

function loopDigraphClusterPrevention(state, config) {
  if (state.prev.token_length > 1 && state.prev.was_consonant) {
    state.prev.was_digraph = true;
    state.log.push('[DIGRAPH] cluster prevention active for prev token');
  }
  return state;
}

function fwdLoopPassthroughNonalpha(state, config) {
  state.output += state.input[state.pos];
  state.pos += 1;
  state.log.push('[FWD PASSTHRU] char: ' + state.input[state.pos - 1]);
  return state;
}

function revPreStripZwj(state, config) {
  const before = state.input;
  state.input = state.input.replace(/\u200D/g, '');
  if (state.input !== before) state.log.push('[REV PRE] ZWJ stripped');
  return state;
}

function preReverseUnknownPassthrough(state, config) {
  config.unknown_char_handling = config.unknown_char_handling ?? 'passthrough';
  return state;
}

function revLoopZwnjVowelSeparator(state, config) {
  const ZWNJ = '\u200C';
  if (state.input[state.pos] !== ZWNJ) return state;
  const prevChar = state.output.slice(-1);
  if (/[aeiouO]/.test(prevChar)) {
    state.pos += 1;
    state.log.push('[REV ZWNJ] swallowed — prev is vowel');
    return state;
  }
  state.output += 'O';
  state.pos += 1;
  state.log.push('[REV ZWNJ] emitted O as vowel separator');
  return state;
}

function revLoopRephPrefix(state, config) {
  const REPH   = '\u09F0'; // ৰ
  const HASANT = '\u09CD'; // ্
  const OPEN_O = '\u09CB'; // ো
  const SPECIAL = ['ৎ', '\u0982', '\u0983', '\u0981'];
  const input = state.input;
  const pos   = state.pos;
  if (!input.startsWith(REPH + HASANT, pos)) return state;
  const consMap    = Object.fromEntries(config.maps.reverse.consonants || []);
  const matraMap   = Object.fromEntries(config.maps.reverse.matras     || []);
  const sortedCons   = Object.keys(consMap).sort((a, b) => b.length - a.length);
  const sortedMatras = Object.keys(matraMap).sort((a, b) => b.length - a.length);
  const consStart  = pos + 2;
  const matchedCons = sortedCons.find(c => input.startsWith(c, consStart));
  if (!matchedCons) return state;
  let nextIdx = consStart + matchedCons.length;
  const hasYaPhala = (input[nextIdx] === HASANT && input[nextIdx + 1] === '\u09AF');
  const hasRaPhala = (input[nextIdx] === HASANT && input[nextIdx + 1] === '\u09F0');
  const conjunctSuffix = hasYaPhala ? 'y' : (hasRaPhala ? 'r' : '');
  if (hasYaPhala || hasRaPhala) nextIdx += 2;
  const matchedMatra   = sortedMatras.find(m => input.startsWith(m, nextIdx));
  const isFollowedByCons = sortedCons.some(c => input.startsWith(c, nextIdx)) && !SPECIAL.includes(matchedCons);
  let engMatra = '';
  if (matchedMatra) {
    engMatra = matchedMatra === OPEN_O ? 'O' : (matraMap[matchedMatra] || '');
  } else if (isFollowedByCons) {
    engMatra = 'o';
  }
  state.output += 'r' + consMap[matchedCons] + conjunctSuffix + engMatra;
  state.pos = nextIdx + (matchedMatra ? matchedMatra.length : 0);
  state.prev.was_consonant = false;
  state.log.push('[REV REPH PREFIX] → r' + consMap[matchedCons] + conjunctSuffix + engMatra);
  return state;
}

function loopReverseInherentVowel(state, config) {
  if (!state.prev.was_consonant) return state;
  const nextChar = state.input[state.pos] || '';
  const matras = (config.maps.reverse.matras || []).map(p => p[0]);
  const isNextMatra  = matras.some(m => nextChar.startsWith(m));
  const isNextVirama = nextChar === config.virama;
  if (!isNextMatra && !isNextVirama) {
    state.output += config.inherent_vowel;
    state.log.push('[INHERENT] added \'' + config.inherent_vowel + '\' after consonant');
  }
  return state;
}

function loopReverseSchwaDeletion(state, config) {
  if (!state.prev.was_consonant) return state;
  const consKeys = (config.maps.reverse.consonants || []).map(p => p[0]);
  const sortedCons = consKeys.sort((a, b) => b.length - a.length);
  const atPos  = state.input.slice(state.pos);
  const isCons = sortedCons.some(c => atPos.startsWith(c));
  if (isCons) {
    if (state.output.endsWith(config.inherent_vowel)) {
      state.output = state.output.slice(0, -config.inherent_vowel.length);
      state.log.push('[SCHWA DEL] inherent vowel suppressed before consecutive consonant');
    }
  }
  return state;
}

function loopReverseReph(state, config) {
  const REPH_CHAR = '\u09F0'; // ৰ
  if (state.input[state.pos] !== REPH_CHAR) return state;
  state.output += 'r';
  state.pos += 1;
  state.prev.was_consonant = true;
  state.log.push('[REPH] ৰ → r at pos ' + state.pos);
  return state;
}

function loopReverseJfala(state, config) {
  const seqs = ['\u09CD\u09AF', '\u09AF']; // ্য, য
  const input = state.input;
  const pos   = state.pos;
  for (const seq of seqs) {
    if (input.slice(pos, pos + seq.length) === seq) {
      state.output += 'y';
      state.pos += seq.length;
      state.prev.was_consonant = false;
      state.log.push('[JFALA] → y at pos ' + pos);
      return state;
    }
  }
  return state;
}

function loopReverseRfala(state, config) {
  const seqs = ['\u09CD\u09F0', '\u09F0']; // ্ৰ, ৰ
  const input = state.input;
  const pos   = state.pos;
  for (const seq of seqs) {
    if (input.slice(pos, pos + seq.length) === seq) {
      state.output += 'r';
      state.pos += seq.length;
      state.prev.was_consonant = false;
      state.log.push('[RFALA] → r at pos ' + pos);
      return state;
    }
  }
  return state;
}

function loopReverseOpenOMatra(state, config) {
  const OPEN_O = '\u09CB'; // ো
  if (state.input[state.pos] !== OPEN_O) return state;
  state.output += 'O';
  state.pos += 1;
  state.prev.was_consonant = false;
  state.log.push('[OPEN-O] ো → O at pos ' + state.pos);
  return state;
}

function revLoopNativeNumbers(state, config) {
  const digitMap = Object.fromEntries(config.maps.reverse.digits || []);
  const ch = state.input[state.pos];
  if (!digitMap[ch]) return state;
  state.output += digitMap[ch];
  state.pos += 1;
  state.prev.was_consonant = false;
  state.log.push('[REV NUM] ' + ch + ' → ' + digitMap[ch]);
  return state;
}

function revLoopSymbolsPunctuation(state, config) {
  const punctMap   = config.maps.reverse.punctuation || [];
  const sortedSyms = [...punctMap].sort((a, b) => b[0].length - a[0].length);
  const input = state.input;
  const pos   = state.pos;
  for (const [sym, latin] of sortedSyms) {
    if (input.startsWith(sym, pos)) {
      state.output += latin;
      state.pos += sym.length;
      state.prev.was_consonant = false;
      state.log.push('[REV SYM] ' + sym + ' → ' + latin);
      return state;
    }
  }
  return state;
}

function revLoopIndependentVowels(state, config) {
  const vowelMap    = Object.fromEntries(config.maps.reverse.independent_vowels || []);
  const sortedVowels = Object.keys(vowelMap).sort((a, b) => b.length - a.length);
  const input = state.input;
  const pos   = state.pos;
  for (const v of sortedVowels) {
    if (input.startsWith(v, pos)) {
      state.output += vowelMap[v];
      state.pos += v.length;
      state.prev.was_consonant = false;
      state.log.push('[REV IND VOWEL] ' + v + ' → ' + vowelMap[v]);
      return state;
    }
  }
  return state;
}

function revLoopConsonantHasantConjunct(state, config) {
  const HASANT = '\u09CD';
  const OPEN_O = '\u09CB';
  const SPECIAL = ['ৎ', '\u0982', '\u0983', '\u0981'];
  const consMap    = Object.fromEntries(config.maps.reverse.consonants || []);
  const matraMap   = Object.fromEntries(config.maps.reverse.matras     || []);
  const sortedCons   = Object.keys(consMap).sort((a, b) => b.length - a.length);
  const sortedMatras = Object.keys(matraMap).sort((a, b) => b.length - a.length);
  const input = state.input;
  const pos   = state.pos;
  const cMatch = sortedCons.find(c => input.startsWith(c, pos));
  if (!cMatch) return state;
  const nextIdx = pos + cMatch.length;
  if (input[nextIdx] !== HASANT) return state;
  const nextCons = sortedCons.find(nc => input.startsWith(nc, nextIdx + 1));
  if (!nextCons) return state;
  const engCons1 = consMap[cMatch];
  const engCons2 = nextCons === '\u09AF' ? 'y' : consMap[nextCons];
  let postIdx = nextIdx + 1 + nextCons.length;
  const hasYaPhala = (input[postIdx] === HASANT && input[postIdx + 1] === '\u09AF');
  const hasRaPhala = (input[postIdx] === HASANT && input[postIdx + 1] === '\u09F0');
  const conjunctSuffix = hasYaPhala ? 'y' : (hasRaPhala ? 'r' : '');
  if (hasYaPhala || hasRaPhala) postIdx += 2;
  const matchedMatra   = sortedMatras.find(m => input.startsWith(m, postIdx));
  const isFollowedByCons = !SPECIAL.includes(nextCons);
  let engMatra = '';
  if (matchedMatra) {
    engMatra = matchedMatra === OPEN_O ? 'O' : (matraMap[matchedMatra] || '');
  } else if (isFollowedByCons) {
    engMatra = 'o';
  }
  state.output += engCons1 + engCons2 + conjunctSuffix + engMatra;
  state.pos = postIdx + (matchedMatra ? matchedMatra.length : 0);
  state.prev.was_consonant = false;
  state.log.push('[REV HASANT] ' + cMatch + '+' + nextCons + conjunctSuffix + engMatra);
  return state;
}

function revLoopConsonantYaphala(state, config) {
  const HASANT = '\u09CD';
  const YA     = '\u09AF';
  const OPEN_O = '\u09CB';
  const consMap    = Object.fromEntries(config.maps.reverse.consonants || []);
  const matraMap   = Object.fromEntries(config.maps.reverse.matras     || []);
  const sortedCons   = Object.keys(consMap).sort((a, b) => b.length - a.length);
  const sortedMatras = Object.keys(matraMap).sort((a, b) => b.length - a.length);
  const input = state.input;
  const pos   = state.pos;
  const cMatch = sortedCons.find(c => input.startsWith(c, pos));
  if (!cMatch) return state;
  const nextIdx = pos + cMatch.length;
  if (!(input[nextIdx] === HASANT && input[nextIdx + 1] === YA)) return state;
  const matraIdx     = nextIdx + 2;
  const matchedMatra = sortedMatras.find(m => input.startsWith(m, matraIdx));
  let engMatra = '';
  if (matchedMatra) {
    engMatra = matchedMatra === OPEN_O ? 'O' : (matraMap[matchedMatra] || '');
  } else {
    engMatra = 'O';
  }
  state.output += consMap[cMatch] + 'y' + engMatra;
  state.pos = matraIdx + (matchedMatra ? matchedMatra.length : 0);
  state.prev.was_consonant = false;
  state.log.push('[REV YAPHALA] ' + cMatch + '+্য+' + engMatra);
  return state;
}

function revLoopConsonantRaphala(state, config) {
  const HASANT  = '\u09CD';
  const ASSA_RA = '\u09F0';
  const OPEN_O  = '\u09CB';
  const consMap    = Object.fromEntries(config.maps.reverse.consonants || []);
  const matraMap   = Object.fromEntries(config.maps.reverse.matras     || []);
  const sortedCons   = Object.keys(consMap).sort((a, b) => b.length - a.length);
  const sortedMatras = Object.keys(matraMap).sort((a, b) => b.length - a.length);
  const input = state.input;
  const pos   = state.pos;
  const cMatch = sortedCons.find(c => input.startsWith(c, pos));
  if (!cMatch) return state;
  const nextIdx = pos + cMatch.length;
  if (!(input[nextIdx] === HASANT && input[nextIdx + 1] === ASSA_RA)) return state;
  const matraIdx     = nextIdx + 2;
  const matchedMatra = sortedMatras.find(m => input.startsWith(m, matraIdx));
  let engMatra = '';
  if (matchedMatra) {
    engMatra = matchedMatra === OPEN_O ? 'O' : (matraMap[matchedMatra] || '');
  } else {
    engMatra = 'o';
  }
  state.output += consMap[cMatch] + 'r' + engMatra;
  state.pos = matraIdx + (matchedMatra ? matchedMatra.length : 0);
  state.prev.was_consonant = false;
  state.log.push('[REV RAPHALA] ' + cMatch + '+্ৰ+' + engMatra);
  return state;
}

function revLoopConsonantStandardMatra(state, config) {
  const OPEN_O  = '\u09CB';
  const SPECIAL = ['ৎ', '\u0982', '\u0983', '\u0981'];
  const consMap    = Object.fromEntries(config.maps.reverse.consonants     || []);
  const matraMap   = Object.fromEntries(config.maps.reverse.matras         || []);
  const vowelMap   = Object.fromEntries(config.maps.reverse.independent_vowels || []);
  const punctMap   = Object.fromEntries(config.maps.reverse.punctuation    || []);
  const sortedCons   = Object.keys(consMap).sort((a, b) => b.length - a.length);
  const sortedMatras = Object.keys(matraMap).sort((a, b) => b.length - a.length);
  const sortedVowels = Object.keys(vowelMap).sort((a, b) => b.length - a.length);
  const sortedSyms   = Object.keys(punctMap).sort((a, b) => b.length - a.length);
  const input = state.input;
  const pos   = state.pos;
  const cMatch = sortedCons.find(c => input.startsWith(c, pos));
  if (!cMatch) return state;
  const nextIdx      = pos + cMatch.length;
  const engCons      = consMap[cMatch];
  const matchedMatra = sortedMatras.find(m => input.startsWith(m, nextIdx));
  if (matchedMatra) {
    const engMatra = matchedMatra === OPEN_O ? 'O' : (matraMap[matchedMatra] || '');
    state.output += engCons + engMatra;
    state.pos = nextIdx + matchedMatra.length;
  } else {
    const nextIsCons  = sortedCons.some(nc => input.startsWith(nc, nextIdx));
    const nextIsVowel = sortedVowels.some(nv => input.startsWith(nv, nextIdx));
    const nextIsSym   = sortedSyms.some(ns => input.startsWith(ns, nextIdx));
    const hasYaPhala  = (input[nextIdx] === '\u09CD' && input[nextIdx + 1] === '\u09AF');
    const addInherent = (nextIsCons || nextIsVowel) && !hasYaPhala && !nextIsSym && !SPECIAL.includes(cMatch);
    state.output += engCons + (addInherent ? 'o' : '');
    state.pos = nextIdx;
  }
  state.prev.was_consonant = true;
  state.log.push('[REV CONS STD] ' + cMatch + ' at pos ' + pos);
  return state;
}

function revLoopFallbackPassthrough(state, config) {
  state.output += state.input[state.pos];
  state.pos += 1;
  state.prev.was_consonant = false;
  state.log.push('[REV PASSTHRU] char: ' + state.input[state.pos - 1]);
  return state;
}

function revPostProtectExplicitO(state, config) {
  state.output = state.output.replace(/O/g, 'PROTECT_O');
  state.output = state.output.replace(/o(?=[.,!?;।])/g, '');
  state.output = state.output.replace(/PROTECT_O/g, 'o');
  state.log.push('[REV POST] explicit-O protected; punctuation-o stripped');
  return state;
}

function revPostStripHasantOArtifacts(state, config) {
  const before = state.output;
  state.output = state.output.replace(/্+o/g, '');
  if (state.output !== before) state.log.push('[REV POST] HASANT+o artifact(s) removed');
  return state;
}

function postStripOBeforePunctuation(state, config) {
  const punct = ['.', ',', '!', '?', ';', '।'];
  const pattern = new RegExp('o(?=[' + punct.map(p => p.replace(/[.*+?^${}()|[\\\\]/g, '\\\\$&')).join('') + '])', 'g');
  const before = state.output;
  state.output = state.output.replace(pattern, '');
  if (state.output !== before) state.log.push('[POST] stripped trailing o before punctuation');
  return state;
}

function postReverseLowercase(state, config) {
  state.output = state.output.toLowerCase();
  state.log.push('[POST] output lowercased');
  return state;
}

function postReverseTrim(state, config) {
  state.output = state.output.trim();
  state.log.push('[POST] output trimmed');
  return state;
}
